Deno.serve(async () => {
  const baseUrl = Deno.env.get("SUPABASE_URL");
  const key = Deno.env.get("SDR_IA_API_KEY");
  if (!baseUrl || !key) return Response.json({ erro: "configuracao_ausente" }, { status: 500 });
  const response = await fetch(`${baseUrl}/functions/v1/sdr-ia-transcrever`, {
    method: "POST",
    headers: { "Content-Type": "application/json", "x-api-key": key },
    body: JSON.stringify({ base64: "", mime: "audio/ogg" }),
  });
  return new Response(await response.text(), { status: response.status, headers: { "Content-Type": "application/json" } });
});
